// ==========================================================================
// עיבוד הדיווחים: סינון של דיווחים שלא אושרו לתשלום ולא שולמו, ובניית טבלת HTML.
// ==========================================================================
//
// התאמה למבנה ה-API של אוריגמי:
// אם התשובה מגיעה במעטפת (למשל { data: [...] }) — עדכנו את השורה שמחלצת את המערך.
// אם שמות השדות שונים אצלכם — עדכנו את המפתחות בפונקציה pick() למטה.

const cfg = $('הגדרות').first().json;
const recipientName = cfg.recipientName || 'מנחם ברקוביץ';
const projectName = cfg.projectName || 'בעל שם טוב';

// --- 1. חילוץ מערך הדיווחים מכל פריטי הכניסה ---
let reports = [];
for (const item of items) {
  const j = item.json;
  if (Array.isArray(j)) reports.push(...j);
  else if (Array.isArray(j.data)) reports.push(...j.data);
  else if (Array.isArray(j.reports)) reports.push(...j.reports);
  else if (Array.isArray(j.results)) reports.push(...j.results);
  else reports.push(j);
}

// --- 2. עוזרים לזיהוי "לא אושר לתשלום" ו-"לא שולם" בצורה עמידה ---
const truthy = (v) => v === true || v === 1 || v === '1' ||
  ['true', 'yes', 'כן', 'מאושר', 'approved', 'paid', 'שולם'].includes(String(v || '').trim().toLowerCase());

const isApprovedForPayment = (r) => truthy(r.approved_for_payment ?? r.payment_approved ?? r.approved ?? r.is_approved) ||
  ['מאושר', 'approved', 'אושר לתשלום'].includes(String(r.payment_status || r.status || '').trim().toLowerCase());

const isPaid = (r) => truthy(r.paid ?? r.is_paid) ||
  ['שולם', 'paid', 'שולם במלואו'].includes(String(r.payment_status || r.status || '').trim().toLowerCase());

// --- 3. סינון: לא אושר לתשלום וגם לא שולם ---
const unpaid = reports.filter((r) => !isApprovedForPayment(r) && !isPaid(r));

// --- 4. עוזרים לפורמט ---
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const fmtDate = (v) => {
  if (!v) return '';
  const d = new Date(v);
  if (isNaN(d.getTime())) return esc(v);
  return d.toLocaleDateString('he-IL', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

const fmtMoney = (v) => {
  const n = Number(String(v == null ? '' : v).replace(/[^0-9.-]/g, ''));
  if (isNaN(n) || v == null || v === '') return '';
  return '₪' + n.toLocaleString('he-IL', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

// --- 5. מיפוי שדות (התאימו לשמות אצלכם במידת הצורך) ---
const pick = (r) => ({
  date: r.report_date ?? r.date ?? r.created_at ?? r.reported_at,
  reporter: r.reporter_name ?? r.reporter ?? r.user_name ?? r.employee ?? r.user?.name,
  description: r.description ?? r.title ?? r.notes ?? r.task ?? r.subject,
  hours: r.hours ?? r.duration ?? r.quantity,
  amount: r.amount ?? r.total ?? r.sum ?? r.price ?? r.cost,
  status: r.status ?? r.payment_status ?? 'לא אושר / לא שולם',
  id: r.id ?? r.report_id ?? r.number,
});

const rows = unpaid.map(pick);

// --- 6. חישוב סכום כולל ---
const totalAmount = rows.reduce((sum, r) => {
  const n = Number(String(r.amount == null ? '' : r.amount).replace(/[^0-9.-]/g, ''));
  return sum + (isNaN(n) ? 0 : n);
}, 0);

// --- 7. תאריך להצגה ---
const now = $now ? $now.toFormat('dd/MM/yyyy') : new Date().toLocaleDateString('he-IL');

// --- 8. בניית ה-HTML ---
const brandColor = '#1f3a5f';
const accent = '#c9a227';

let tableRowsHtml;
if (rows.length === 0) {
  tableRowsHtml = `<tr><td colspan="6" style="padding:18px;text-align:center;color:#6b7280;">\u2705 אין דיווחים ממתינים \u2013 כל הדיווחים אושרו/שולמו.</td></tr>`;
} else {
  tableRowsHtml = rows.map((r, i) => `
    <tr style="background:${i % 2 ? '#f7f8fa' : '#ffffff'};">
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;white-space:nowrap;">${fmtDate(r.date)}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;">${esc(r.reporter)}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;">${esc(r.description)}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;text-align:center;">${esc(r.hours)}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;text-align:left;white-space:nowrap;">${fmtMoney(r.amount)}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;">
        <span style="display:inline-block;background:#fdecea;color:#b42318;border-radius:12px;padding:2px 10px;font-size:12px;font-weight:600;">${esc(r.status)}</span>
      </td>
    </tr>`).join('');
}

const totalRowHtml = rows.length ? `
    <tr style="background:${brandColor};color:#ffffff;font-weight:700;">
      <td colspan="4" style="padding:12px;text-align:right;">\u05e1\u05d4\"\u05db (${rows.length} \u05d3\u05d9\u05d5\u05d5\u05d7\u05d9\u05dd)</td>
      <td style="padding:12px;text-align:left;white-space:nowrap;">${fmtMoney(totalAmount)}</td>
      <td style="padding:12px;"></td>
    </tr>` : '';

const html = `<!DOCTYPE html>
<html lang="he" dir="rtl">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#eef1f5;font-family:'Segoe UI',Arial,'Helvetica Neue',sans-serif;color:#111827;">
  <div style="max-width:760px;margin:0 auto;padding:24px;">
    <div style="background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 4px 18px rgba(0,0,0,0.08);">
      <div style="background:linear-gradient(135deg, ${brandColor}, #2c527f);padding:26px 28px;">
        <div style="color:${accent};font-size:13px;letter-spacing:1px;font-weight:600;">SLAVITA PUBLISHING</div>
        <h1 style="margin:6px 0 0;color:#ffffff;font-size:22px;">סיכום דיווחים – פרויקט "${esc(projectName)}"</h1>
        <div style="margin-top:6px;color:#d7e0ec;font-size:14px;">דיווחים שטרם אושרו לתשלום וטרם שולמו &nbsp;\u2022&nbsp; הופק בתאריך ${now}</div>
      </div>
      <div style="padding:22px 28px 8px;">
        <p style="margin:0 0 14px;font-size:15px;">שלום ${esc(recipientName)},</p>
        <p style="margin:0 0 18px;font-size:15px;line-height:1.6;color:#374151;">להלן סיכום כל הדיווחים בפרויקט <strong>"${esc(projectName)}"</strong> מתוך מערכת אוריגמי, שטרם אושרו לתשלום וטרם שולמו נכון להיום.</p>
      </div>
      <div style="padding:0 28px 26px;">
        <table style="width:100%;border-collapse:collapse;font-size:14px;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">
          <thead>
            <tr style="background:#f3f4f6;text-align:right;">
              <th style="padding:12px;border-bottom:2px solid #e5e7eb;font-weight:700;">תאריך</th>
              <th style="padding:12px;border-bottom:2px solid #e5e7eb;font-weight:700;">מדווח</th>
              <th style="padding:12px;border-bottom:2px solid #e5e7eb;font-weight:700;">תיאור</th>
              <th style="padding:12px;border-bottom:2px solid #e5e7eb;font-weight:700;text-align:center;">שעות</th>
              <th style="padding:12px;border-bottom:2px solid #e5e7eb;font-weight:700;text-align:left;">סכום</th>
              <th style="padding:12px;border-bottom:2px solid #e5e7eb;font-weight:700;">סטטוס</th>
            </tr>
          </thead>
          <tbody>
            ${tableRowsHtml}
            ${totalRowHtml}
          </tbody>
        </table>
      </div>
      <div style="padding:16px 28px;background:#f9fafb;border-top:1px solid #eef1f5;color:#6b7280;font-size:12px;">
        הודעה זו נשלחה אוטומטית ממערכת האוטומציה (n8n) בהתבסס על נתוני אוריגמי. &nbsp;\u2022&nbsp; סלאוויטא
      </div>
    </div>
  </div>
</body>
</html>`;

const subject = rows.length
  ? `סיכום דיווחים לתשלום – פרויקט "${projectName}" (${rows.length} דיווחים, ${fmtMoney(totalAmount)})`
  : `סיכום דיווחים – פרויקט "${projectName}" – אין דיווחים ממתינים`;

return [{
  json: {
    subject,
    html,
    count: rows.length,
    totalAmount,
    recipientEmail: cfg.recipientEmail,
    recipientName,
  }
}];
